import { field, select, checkbox, textarea, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${select({ id: "zcType", label: "Zstandard use case", options: [{label:"Static assets (CSS, JS, fonts)",value:"assets"},{label:"API responses (JSON)",value:"api"},{label:"HTML pages",value:"html"},{label:"All content types",value:"all"}], value: "assets" })}${select({ id: "zcServer", label: "Server platform", options: [{label:"Nginx",value:"nginx"},{label:"Apache",value:"apache"},{label:"Cloudflare",value:"cloudflare"},{label:"Netlify",value:"netlify"}], value: "nginx" })}</div><div class="field-grid">${checkbox({ id: "zcDict", label: "Include shared dictionary compression (Delta)", checked: false })}${checkbox({ id: "zcFallback", label: "Include gzip/brotli fallback", checked: true })}</div>`,generate(root) {const type = root.querySelector("#zcType").value;const server = root.querySelector("#zcServer").value;const dict = root.querySelector("#zcDict").checked;const fallback = root.querySelector("#zcFallback").checked;const contentTypes = {assets: "text/css text/javascript application/javascript font/woff2 image/svg+xml",api: "application/json",html: "text/html",all: ""};const ct = contentTypes[type];const lines = [];lines.push("# Zstandard (zstd) Compression Headers — Baseline 2026");lines.push("# Browser: Chrome 123+, Edge 123+, Safari 18+, Firefox 133+");lines.push("# Zstandard offers better compression ratios than brotli at similar speeds.");lines.push("");if (server === "nginx") {lines.push("# Nginx configuration");lines.push("# Requires: ngx_http_zstd_filter_module or compile with --with-zstd");lines.push("");if (ct) lines.push(`# Content types: ${ct}`);if (ct) {lines.push(`zstd_types ${ct};`);} else {lines.push("zstd on;");}lines.push("zstd_comp_level 6;");lines.push("");} else if (server === "apache") {lines.push("# Apache configuration");lines.push("# Requires: mod_zstd");lines.push("");if (ct) {lines.push(`AddOutputFilterByType ZSTD ${ct}`);} else {lines.push("SetOutputFilter ZSTD");}lines.push("ZstdCompressionLevel 6");lines.push("");} else if (server === "cloudflare") {lines.push("# Cloudflare — enable in Dashboard");lines.push("# Speed > Optimization > Content Optimization > Auto Minify");lines.push("# Cloudflare automatically serves zstd to supporting browsers alongside brotli.");lines.push("# No server configuration needed — handled at the edge.");lines.push("");} else if (server === "netlify") {lines.push("# Netlify — use custom headers in netlify.toml or _headers");lines.push("[[headers]]");lines.push(" for = \"/*\"");lines.push(" [headers.values]");lines.push(' Content-Encoding = "zstd"');lines.push("");lines.push("# Note: Netlify should be configured to pre-compress assets during deploy.");lines.push("# Use a build plugin or pre-compress script to generate .zst files.");}if (fallback) {lines.push("# Content Negotiation: Accept-Encoding header");lines.push("# Browsers send: Accept-Encoding: gzip, br, zstd");lines.push("# Server picks the best encoding the browser supports.");lines.push("# Priority: zstd > br > gzip (for browsers that support zstd).");}if (dict) {lines.push("");lines.push("# Shared Dictionary Compression (Delta compression)");lines.push("# Available-Encoding: zstd, br, gzip");lines.push("# Use-Dictionary: <dictionary-hash>");lines.push("# Enables delta compression — only send the diff between versions.");lines.push("# Requires: Shared Dictionary for Compression API (Chrome 130+).");}lines.push("");lines.push("# Vary header — important for CDN caching");lines.push("Vary: Accept-Encoding");lines.push("");lines.push("# Notes:");lines.push("# 1. Zstandard compresses 5-15% better than brotli at comparable speeds.");lines.push("# 2. Compression level 3-6 is the sweet spot for dynamic content.");lines.push("# 3. Pre-compress static assets at max level (19-22) for best results.");lines.push("# 4. For shared hosting without zstd support, rely on brotli via CDN.");const preview = `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:14px;background:#f9fafb"><div style="font-size:13px;font-weight:600;color:#374151;margin-bottom:8px">Zstandard for ${server} — ${type}</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px"><span style="background:#dcfce7;color:#166534;padding:3px 10px;border-radius:12px;font-size:11px">5-15% better than Brotli</span>${fallback ? '<span style="background:#dbeafe;color:#1e40af;padding:3px 10px;border-radius:12px;font-size:11px">gzip/brotli fallback</span>' : ""}${dict ? '<span style="background:#fef3c7;color:#92400e;padding:3px 10px;border-radius:12px;font-size:11px">Delta compression</span>' : ""}</div><div style="font-size:12px;color:#6b7280">Accept-Encoding: zstd, br, gzip</div></div>`;return { output: lines.join("\n"), preview };}};